import{_ as t,c as r,a5 as s,o as n}from"./chunks/framework.DoP1wijR.js";const a="/pub-blog/assets/IMG_20251208_174554.DSQAJPef.jpg",g="/pub-blog/assets/IMG_20251208_174620.DoBum95q.jpg",p="/pub-blog/assets/wx_camera_1765114557017.vMVoES0c.jpg",e="/pub-blog/assets/image-20251213220307735.gjVudMZ1.png",l="/pub-blog/assets/PixPin_2025-12-13_22-06-27.2EKBk9PS.png",m=JSON.parse('{"title":"这个鸿蒙作品，是大三学生三天完成的，你相信吗？","description":"","frontmatter":{},"headers":[],"relativePath":"鸿蒙开发技巧/这个鸿蒙作品，是大三学生三天完成的，你相信吗/这个鸿蒙作品，是大三学生三天完成的，你相信吗.md","filePath":"鸿蒙开发技巧/这个鸿蒙作品，是大三学生三天完成的，你相信吗/这个鸿蒙作品，是大三学生三天完成的，你相信吗.md","lastUpdated":1765726127000}'),i={name:"鸿蒙开发技巧/这个鸿蒙作品，是大三学生三天完成的，你相信吗/这个鸿蒙作品，是大三学生三天完成的，你相信吗.md"};function h(u,o,c,b,d,q){return n(),r("div",null,o[0]||(o[0]=[s('<h1 id="这个鸿蒙作品-是大三学生三天完成的-你相信吗" tabindex="-1">这个鸿蒙作品，是大三学生三天完成的，你相信吗？ <a class="header-anchor" href="#这个鸿蒙作品-是大三学生三天完成的-你相信吗" aria-label="Permalink to &quot;这个鸿蒙作品，是大三学生三天完成的，你相信吗？&quot;">​</a></h1><blockquote><p><strong>三天</strong>，<strong>72小时</strong>，<strong>4320分钟</strong><br> 一群大三学生，从零开始，用鸿蒙开发一个抖音应用<br> 你觉得，这可能吗？</p></blockquote><h2 id="前言" tabindex="-1">前言 <a class="header-anchor" href="#前言" aria-label="Permalink to &quot;前言&quot;">​</a></h2><p>作为一个有多年开发经验的程序员，我承认：<strong>一开始，我是不信的</strong>。</p><p>直到我亲眼见证了这一切...</p><p>这几天负责了广州某个本科院校为期4天的<strong>鸿蒙6应用开发实训</strong>，虽说是4天，实际是<strong>两天半</strong>，每一天6个小时，最后的验收成果还是<strong>收获满满</strong>的。</p><blockquote><p>这次实训让我看到了当代大学生的潜力和创造力，也让我对年轻一代有了新的认识。</p></blockquote><h2 id="风景一览" tabindex="-1">风景一览 <a class="header-anchor" href="#风景一览" aria-label="Permalink to &quot;风景一览&quot;">​</a></h2><p>回到校园，仿佛又回到了那个青葱岁月...</p><p>高校的生活、学习环境我一直都认为是<strong>最好的，没有之一</strong>！</p><p>进入校园有一定的安检、有<strong>环境舒适、安静</strong>的图书馆、有<strong>物美价廉、安全卫生</strong>的食堂、有<strong>基础设施完善</strong>的运动场，还有一大群<strong>充满朝气活力</strong>的大学生！</p><blockquote><p>相较于在社会上摸爬滚打的牛马们，还有更好的选择吗？相比较于在社会上摸爬滚打的牛马们，还有更好的选择吗？</p></blockquote><p><img src="'+a+'" alt="IMG_20251208_174554"></p><hr><p><img src="'+g+'" alt="IMG_20251208_174620"></p><hr><p><img src="'+p+'" alt="wx_camera_1765114557017"></p><p><img src="'+e+'" alt="image-20251213220307735"></p><h2 id="实训主题" tabindex="-1">实训主题 <a class="header-anchor" href="#实训主题" aria-label="Permalink to &quot;实训主题&quot;">​</a></h2><p><strong>挑战任务：4天时间，用鸿蒙开发一个抖音应用！</strong></p><p>这一次的实训主题是在这4天内使用<strong>最新的HarmonyOS6</strong>、V2状态管理、<strong>Navigation</strong>、<strong>Video</strong>等技术开发一个具有核心功能的抖音应用案例，由于是<strong>纯鸿蒙端</strong>的实训，因此只考虑前端内容，不要求后端能力。</p><blockquote><p>任务看似简单，但学生们的表现却超出了所有人的预期。</p></blockquote><p><img src="'+l+'" alt="img"></p><h2 id="实训过程" tabindex="-1">实训过程 <a class="header-anchor" href="#实训过程" aria-label="Permalink to &quot;实训过程&quot;">​</a></h2><p><strong>第一天</strong>：学生们陆续到场，各种表情都有。</p><p>实训过程中我的感觉其实和普通院校的情况类似，不乏听课认真的同学，也有上来就直说对鸿蒙不感兴趣，希望最后答辩可以放一马的小伙子，也有过程一直佛系、扣手机、玩游戏、蓬头垢面的年轻人。</p><p>我初步以为这个实训其实也是平平淡淡的过去了。</p><p>但现实总是充满惊喜...</p><p>​ 等到最后答辩的时候，挺多让我意外的情况出现：</p><hr><h3 id="答辩要求远超我预期" tabindex="-1">答辩要求远超我预期 <a class="header-anchor" href="#答辩要求远超我预期" aria-label="Permalink to &quot;答辩要求远超我预期&quot;">​</a></h3><p><strong>答辩当天，我被彻底震撼了！</strong></p><p>我要求不需要后端，纯鸿蒙端的能力即可，但是实际最后答辩中，有<strong>三分之二</strong>的同学是<strong>主动使用</strong>之前上课学习过的后端知识，<strong>主动去搭建</strong>后端架构、完成登录、注册、发布视频、关注、互关、实时消息、甚至AI聊天助手，甚至也有自己拓展使用了鸿蒙的AI能力-<strong>AI语音识别</strong>等。</p><p>这份自觉确实让我吓一跳。</p><p>最大的感受就是，过程你可能会发现他们在放松做其他的，但是实际的效果足以说明<strong>背后他们花费的时间成本</strong>。</p><blockquote><p><strong>你以为的佛系，只是他们不想让你看到努力的样子。</strong></p></blockquote><hr><h3 id="对鸿蒙不感兴趣-小a-重点学习爬虫了" tabindex="-1">对鸿蒙不感兴趣-小A-重点学习爬虫了 <a class="header-anchor" href="#对鸿蒙不感兴趣-小a-重点学习爬虫了" aria-label="Permalink to &quot;对鸿蒙不感兴趣-小A-重点学习爬虫了&quot;">​</a></h3><p><strong>&quot;老师，我对鸿蒙不感兴趣。&quot;</strong></p><p>这是小A第一天对我说的话。</p><p>过程中，也有同学给我讲了<strong>对鸿蒙不感兴趣</strong>。小A不打算投入太多时间学习鸿蒙，但是他过程中是<strong>花了很多时间</strong>去使用python<strong>实时爬取douyin的资料</strong>，然后<strong>部署成后端</strong>，同时鸿蒙端结合<strong>AI编程</strong>，可以<strong>实时预览douyin视频数据</strong>。</p><p>虽然小A明确表示对鸿蒙不感兴趣，但是也是<strong>付出了一些成本</strong>完成了鸿蒙端的要求。这<strong>比很多人借口不感兴趣</strong>，然后什么都不做要强太多了，这个让我意识到，学生是<strong>知道什么是兴趣</strong>、<strong>什么是工作的</strong>。</p><blockquote><p><strong>不感兴趣，不代表不负责。这是一种成熟的表现。</strong></p></blockquote><hr><p>​ 这一点我思考了很久，我仅仅以为过程中他们部分同学出现的散漫，就以为他们对自己是没有要求和目标的，但是实际上证明我是错的，网络上喧嚣着年轻一代-在短视频时代花更少的成本更容易获得精神上的满足，不会愿意花大量时间去投入学习编程，接近反人性的一种学习体验，但是这个答辩结果恰恰可以证明很多年轻人其实也是付出在背后，其实也是对自己有高要求的。</p><h3 id="敢勇敢发声" tabindex="-1">敢勇敢发声 <a class="header-anchor" href="#敢勇敢发声" aria-label="Permalink to &quot;敢勇敢发声&quot;">​</a></h3><p>​ 这个是答辩过程的一个小插曲，我们实训实际分成10个小组。正常情况到答辩开始就从第一组开始，按顺序往下就行。我作为组织者，也自然这样安排下去。答辩方法刚讲完，底下就有学生说 <strong>&quot;哪一组完成哪一组就直接上就行&quot;</strong>。作为组织者一听，这个安排自然有漏洞，万一所有组都没有完成，那么就无法开始答辩了。和我同行的老师就直接拿麦克风提出了这个问题，并且继续我们已有的安排。学生继续回应 <strong>&quot;有一些组还没有完成，上去讲也没有用，一些组完成了，提前上去有什么问题&quot;</strong> 。。。 老师和学生的质疑继续进行。我这会问了下底下的同学是否以前也是这样的，学生回答是。听到这个结论，我是愿意相信学生的话，然后就按照这个建议开始。最后，虽然上去答辩的顺序有些打乱，但是最后也是完成了的。</p><p>​ 这个结果足以证明，<strong>几乎所有的学生都是有准备</strong>可以上台答辩的，他们要求慢一些，其实也是<strong>希望继续打磨自己的作品</strong>，否则，直接上去敷衍摆烂，也比争取多一些时间要干净利落。</p><h3 id="对鸿蒙不感兴趣-小a-重点学习爬虫了-1" tabindex="-1">对鸿蒙不感兴趣-小A-重点学习爬虫了 <a class="header-anchor" href="#对鸿蒙不感兴趣-小a-重点学习爬虫了-1" aria-label="Permalink to &quot;对鸿蒙不感兴趣-小A-重点学习爬虫了&quot;">​</a></h3><p>​ 过程中，也有同学给我讲了<strong>对鸿蒙不感兴趣</strong>。小A不打算投入太多时间学习鸿蒙，但是他过程中是<strong>花了很多时间</strong>去使用python<strong>实时爬取douyin的资料</strong>，然后<strong>部署成后端</strong>，同时鸿蒙端结合<strong>AI编程</strong>，可以<strong>实时预览douyin视频数据</strong>。</p><p>​ 虽然小A明确表示对鸿蒙不感兴趣，但是也是<strong>付出了一些成本</strong>完成了鸿蒙端的要求。这<strong>比很多人借口不感兴趣</strong>，然后什么都不做要强太多了，这个让我意识到，学生是<strong>知道什么是兴趣</strong>、<strong>什么是工作的</strong>。我们社会人应该很清楚了，工作很多时候无所谓兴趣，但是就是要完成。小A明显也做到了，而且自己也知道这个爬虫的动作容易触边。</p><h3 id="对鸿蒙不感兴趣-小b-被迫跟着写鸿蒙了" tabindex="-1">对鸿蒙不感兴趣-小B-被迫跟着写鸿蒙了 <a class="header-anchor" href="#对鸿蒙不感兴趣-小b-被迫跟着写鸿蒙了" aria-label="Permalink to &quot;对鸿蒙不感兴趣-小B-被迫跟着写鸿蒙了&quot;">​</a></h3><p><strong>&quot;老师，我真的不想学鸿蒙...&quot;</strong></p><p>小B也是开口对鸿蒙不感兴趣，我们作为老师自然万般都理解，但是我们老师的工作也是需要验收这次实训的成果，何况是素未谋面的学生，他自己说不感兴趣，是真的不感兴趣，还是他什么兴趣都没有，如果是后者，我们老师其实是需要<strong>连哄带骗</strong>让学生学习东西了，如果能让他在过程中<strong>找到一些乐趣</strong>，是否也当帮助了一把学生呢。</p><p>最后，这个学生是磕磕碰碰的完成了上课的所有要求和任务，我也是实时鼓励学生：</p><blockquote><p><strong>&quot;行动起来远比你呆看不做要容易轻松得多&quot;</strong></p></blockquote><blockquote><p><strong>有时候，推一把，就是一片新天地。</strong></p></blockquote><hr><h2 id="优秀作品示例" tabindex="-1">优秀作品示例 <a class="header-anchor" href="#优秀作品示例" aria-label="Permalink to &quot;优秀作品示例&quot;">​</a></h2><p><strong>这些作品，真的只是三天完成的吗？</strong></p><p>是的，你没看错！</p><hr><h2 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h2><p><strong>&quot;现在学习编程，是 49年入国军&quot;</strong></p><p>最近这几年的互联网就业形势，相信大家也不陌生，网友也是时刻调侃这句话。</p><p>但我想说：</p><p><strong>不要轻易相信网络上的声音，更不要轻易给年轻人下定义。</strong></p><p>这里我也想聊下我的看法：</p><ol><li><p>互联网还是<strong>普通人实现阶层跨越</strong>的一个好的渠道</p></li><li><p>互联网的<strong>上升路线是透明的</strong>，有无数多的学习资料，收费、免费、还有现在的AI加持</p></li><li><p>如果让你给他们建议，不做互联网，你会让他们做什么，网络的言论很容易，<strong>反对一切、批评一切就行</strong>，但是<strong>不会提出实际、可行、目前的建议</strong>。</p></li></ol><hr><p><strong>写在最后：</strong></p><p>这次实训让我明白，不要轻易给年轻人贴标签。他们或许表面看起来佛系，但内心却有着自己的追求和坚持。</p><p><strong>三天完成一个鸿蒙应用，你相信吗？</strong></p><p><strong>我信了。</strong></p><p><strong>因为，我亲眼见证了这一切。</strong></p><hr><blockquote><p><strong>如果你也是一名大学生，或者曾经是，</strong><strong>如果你也对技术充满热情，</strong><strong>欢迎在评论区分享你的故事。</strong></p></blockquote>',77)]))}const k=t(i,[["render",h]]);export{m as __pageData,k as default};
